-- Name: agent_channel_message_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_channel_message_t (
    host_id uuid NOT NULL,
    message_id uuid NOT NULL,
    binding_id uuid NOT NULL,
    external_event_id character varying(255) NOT NULL,
    response_destination character varying(512) NOT NULL,
    direction character varying(16) NOT NULL,
    payload_digest character varying(71) NOT NULL,
    state character varying(32) NOT NULL,
    turn_id uuid,
    attempt_count integer DEFAULT 0 NOT NULL,
    next_attempt_ts timestamp with time zone,
    receipt jsonb,
    created_ts timestamp with time zone DEFAULT now() NOT NULL,
    updated_ts timestamp with time zone DEFAULT now() NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    provider_receipt_id character varying(255),
    last_error jsonb,
    attachment_scan_state character varying(16) DEFAULT 'NOT_REQUIRED'::character varying NOT NULL,
    scan_claim_token uuid,
    scan_lease_expires_ts timestamp with time zone,
    scan_attempt_count integer DEFAULT 0 NOT NULL,
    next_scan_attempt_ts timestamp with time zone,
    connector_grant_id uuid,
    connector_data_boundary_digest character varying(128),
    CONSTRAINT agent_channel_attachment_scan_state_ck CHECK ((((attachment_scan_state)::text = ANY (ARRAY[('NOT_REQUIRED'::character varying)::text, ('PENDING'::character varying)::text, ('CLAIMED'::character varying)::text, ('CLEAN'::character varying)::text, ('REJECTED'::character varying)::text])) AND (scan_attempt_count >= 0) AND ((((attachment_scan_state)::text = 'CLAIMED'::text) AND (scan_claim_token IS NOT NULL) AND (scan_lease_expires_ts IS NOT NULL)) OR (((attachment_scan_state)::text <> 'CLAIMED'::text) AND (scan_claim_token IS NULL) AND (scan_lease_expires_ts IS NULL))))),
    CONSTRAINT agent_channel_message_t_direction_check CHECK (((direction)::text = ANY (ARRAY[('INBOUND'::character varying)::text, ('OUTBOUND'::character varying)::text]))),
    CONSTRAINT agent_channel_message_t_state_check CHECK (((state)::text = ANY (ARRAY[('RECEIVED'::character varying)::text, ('TURN_CREATED'::character varying)::text, ('PENDING_DELIVERY'::character varying)::text, ('SENDING'::character varying)::text, ('DELIVERED'::character varying)::text, ('FAILED'::character varying)::text, ('REJECTED'::character varying)::text])))
);


