CREATE TABLE public.agent_definition_t (
    host_id uuid NOT NULL,
    agent_def_id uuid NOT NULL,
    model_provider character varying(64),
    model_name character varying(126),
    api_key_ref character varying(126),
    temperature numeric(3,2) DEFAULT 0.7,
    max_tokens integer,
    aggregate_version bigint DEFAULT 1 NOT NULL,
    active boolean DEFAULT true,
    update_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    update_user character varying(126) DEFAULT SESSION_USER,
    product_profile character varying(32) DEFAULT 'enterprise'::character varying NOT NULL,
    default_execution_profile_id character varying(126),
    policy_snapshot jsonb,
    policy_digest character varying(71),
    maximum_session_seconds bigint,
    maximum_turn_seconds bigint,
    materializer_id character varying(126) DEFAULT 'enterprise'::character varying NOT NULL,
    materializer_version integer DEFAULT 1 NOT NULL,
    skill_selection_policy jsonb DEFAULT '{}'::jsonb NOT NULL,
    model_alias_id uuid,
    model_policy_id uuid,
    CONSTRAINT agent_definition_model_selection_ck CHECK (((NOT ((model_alias_id IS NOT NULL) AND (model_policy_id IS NOT NULL))) AND ((model_alias_id IS NOT NULL) OR (model_policy_id IS NOT NULL) OR ((model_provider IS NOT NULL) AND (model_name IS NOT NULL))) AND ((model_provider IS NULL) = (model_name IS NULL)) AND (((model_alias_id IS NULL) AND (model_policy_id IS NULL)) OR (api_key_ref IS NULL))))
);


