-- Name: agent_quota_policy_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_quota_policy_t (
    host_id uuid NOT NULL,
    quota_id uuid NOT NULL,
    scope_kind character varying(16) NOT NULL,
    scope_key character varying(255) NOT NULL,
    maximum_active_sessions integer,
    maximum_queued_turns integer,
    maximum_running_turns integer,
    token_budget_per_window bigint,
    cost_budget_micros_per_window bigint,
    window_seconds integer DEFAULT 60 NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    created_ts timestamp with time zone DEFAULT now() NOT NULL,
    updated_ts timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_quota_nonnegative_ck CHECK ((((maximum_active_sessions IS NULL) OR (maximum_active_sessions >= 0)) AND ((maximum_queued_turns IS NULL) OR (maximum_queued_turns >= 0)) AND ((maximum_running_turns IS NULL) OR (maximum_running_turns >= 0)) AND ((token_budget_per_window IS NULL) OR (token_budget_per_window >= 0)) AND ((cost_budget_micros_per_window IS NULL) OR (cost_budget_micros_per_window >= 0)))),
    CONSTRAINT agent_quota_policy_t_scope_kind_check CHECK (((scope_kind)::text = ANY (ARRAY[('HOST'::character varying)::text, ('PRINCIPAL'::character varying)::text, ('AGENT'::character varying)::text, ('PROFILE'::character varying)::text, ('PROVIDER'::character varying)::text, ('POOL'::character varying)::text]))),
    CONSTRAINT agent_quota_policy_t_window_seconds_check CHECK (((window_seconds >= 1) AND (window_seconds <= 86400)))
);


