-- Name: agent_trigger_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_trigger_t (
    host_id uuid NOT NULL,
    trigger_id uuid NOT NULL,
    binding_id uuid NOT NULL,
    trigger_kind character varying(32) NOT NULL,
    schedule_or_cursor jsonb NOT NULL,
    budget jsonb NOT NULL,
    maximum_delay_seconds integer NOT NULL,
    state character varying(16) NOT NULL,
    next_fire_ts timestamp with time zone,
    created_ts timestamp with time zone DEFAULT now() NOT NULL,
    connector_grant_id uuid,
    last_fire_ts timestamp with time zone,
    last_idempotency_key character varying(255),
    timezone character varying(64) DEFAULT 'UTC'::character varying NOT NULL,
    fire_count bigint DEFAULT 0 NOT NULL,
    misfire_policy character varying(16) DEFAULT 'SKIP'::character varying NOT NULL,
    maximum_catch_up_fires integer DEFAULT 1 NOT NULL,
    last_misfire_ts timestamp with time zone,
    misfire_count bigint DEFAULT 0 NOT NULL,
    skipped_fire_count bigint DEFAULT 0 NOT NULL,
    last_error jsonb,
    updated_ts timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_trigger_runtime_policy_ck CHECK ((((misfire_policy)::text = ANY (ARRAY[('SKIP'::character varying)::text, ('FIRE_ONCE'::character varying)::text, ('CATCH_UP'::character varying)::text])) AND ((maximum_catch_up_fires >= 1) AND (maximum_catch_up_fires <= 10)) AND (maximum_delay_seconds >= 0) AND (misfire_count >= 0) AND (skipped_fire_count >= 0) AND (jsonb_typeof(budget) = 'object'::text))),
    CONSTRAINT agent_trigger_t_state_check CHECK (((state)::text = ANY (ARRAY[('ACTIVE'::character varying)::text, ('PAUSED'::character varying)::text, ('REVOKED'::character varying)::text]))),
    CONSTRAINT agent_trigger_t_trigger_kind_check CHECK (((trigger_kind)::text = ANY (ARRAY[('SCHEDULE'::character varying)::text, ('CONNECTOR'::character varying)::text])))
);


