-- Name: api_endpoint_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.api_endpoint_t (
    host_id uuid NOT NULL,
    endpoint_id uuid NOT NULL,
    api_version_id uuid NOT NULL,
    endpoint character varying(1024) NOT NULL,
    http_method character varying(10),
    endpoint_path character varying(1024),
    endpoint_name character varying(128) NOT NULL,
    tool_schema text,
    response_schema text,
    tool_metadata text,
    routing_domain character varying(128),
    semantic_namespace character varying(128),
    sensitivity_tier character varying(64),
    semantic_weight real DEFAULT 1.0,
    source_protocol character varying(50),
    lifecycle_status character varying(32) DEFAULT 'active'::character varying,
    cost_tier character varying(32),
    target_personas text,
    endpoint_desc text,
    active boolean DEFAULT true NOT NULL,
    delete_user character varying(255),
    delete_ts timestamp with time zone,
    update_user character varying(255) DEFAULT SESSION_USER NOT NULL,
    update_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT api_endpoint_t_http_method_check CHECK (((http_method)::text = ANY (ARRAY[('delete'::character varying)::text, ('get'::character varying)::text, ('patch'::character varying)::text, ('post'::character varying)::text, ('put'::character varying)::text, ('call'::character varying)::text]))),
    CONSTRAINT chk_api_endpoint_cost CHECK ((((cost_tier)::text = ANY (ARRAY[('low'::character varying)::text, ('medium'::character varying)::text, ('high'::character varying)::text])) OR (cost_tier IS NULL))),
    CONSTRAINT chk_api_endpoint_lifecycle CHECK (((lifecycle_status IS NOT NULL) AND ((lifecycle_status)::text = ANY (ARRAY[('active'::character varying)::text, ('deprecated'::character varying)::text, ('retired'::character varying)::text])))),
    CONSTRAINT chk_api_endpoint_source_protocol CHECK ((((source_protocol)::text = ANY (ARRAY[('openapi'::character varying)::text, ('mcp'::character varying)::text, ('lightapi'::character varying)::text, ('http'::character varying)::text])) OR (source_protocol IS NULL)))
);


