--
-- Name: auth_client_owner_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.auth_client_owner_t (
    host_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    owner_type character varying(32) NOT NULL,
    app_id character varying(512),
    api_version_id uuid,
    instance_id uuid,
    owner_name character varying(126) NOT NULL,
    description character varying(1024),
    contact_email character varying(255),
    review_ts timestamp with time zone,
    active boolean DEFAULT true NOT NULL,
    delete_user character varying(255),
    delete_ts timestamp with time zone,
    update_user character varying(255) DEFAULT SESSION_USER NOT NULL,
    update_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT auth_client_owner_t_check CHECK (((((owner_type)::text = 'app'::text) AND (app_id IS NOT NULL) AND (api_version_id IS NULL) AND (instance_id IS NULL)) OR (((owner_type)::text = 'api_version'::text) AND (app_id IS NULL) AND (api_version_id IS NOT NULL) AND (instance_id IS NULL)) OR (((owner_type)::text = 'instance'::text) AND (app_id IS NULL) AND (api_version_id IS NULL) AND (instance_id IS NOT NULL)) OR (((owner_type)::text = 'service_account'::text) AND (app_id IS NULL) AND (api_version_id IS NULL) AND (instance_id IS NULL) AND (contact_email IS NOT NULL))))
);


