    root_instance_id uuid,
    graph_revision bigint,
    clone_request_id uuid,
    source_processor character varying(16) NOT NULL,
    source_topic character varying(255),
    source_partition integer,
    source_offset bigint NOT NULL,
    source_key bytea,
    source_headers jsonb DEFAULT '[]'::jsonb NOT NULL,
    payload_format character varying(32) NOT NULL,
    payload_digest character varying(64) NOT NULL,
    payload_storage character varying(16) NOT NULL,
    payload_ciphertext bytea,
    payload_object_uri character varying(2048),
    payload_object_version character varying(255),
    payload_key_id character varying(255),
    payload_wrapped_key bytea,
    payload_iv bytea,
    encrypted_payload_bytes bigint NOT NULL,
    decrypted_payload_bytes bigint NOT NULL,
    sensitive_payload boolean DEFAULT false NOT NULL,
    payload_deleted_ts timestamp with time zone,
    payload_deleted_reason character varying(1024),
    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    payload_plain bytea,
    event_schema_version character varying(64),
    policy_registry_version character varying(64) DEFAULT 'event-replay-policy-v1'::character varying NOT NULL,
    repair_schema_version character varying(64),
    CONSTRAINT event_failure_event_bytes_ck CHECK (((encrypted_payload_bytes >= 0) AND (decrypted_payload_bytes >= 0) AND (((payload_storage)::text <> 'DATABASE_PLAIN'::text) OR ((encrypted_payload_bytes = 0) AND (decrypted_payload_bytes = octet_length(payload_plain)))))),
    CONSTRAINT event_failure_event_coordinates_ck CHECK (((((source_processor)::text = 'DATABASE'::text) AND (source_topic IS NULL) AND (source_partition IS NOT NULL)) OR (((source_processor)::text = 'KAFKA'::text) AND (source_topic IS NOT NULL) AND (source_partition IS NOT NULL)))),
    CONSTRAINT event_failure_event_crypto_ck CHECK ((((payload_storage)::text = ANY (ARRAY[('DATABASE_PLAIN'::character varying)::text, ('DELETED'::character varying)::text])) OR ((octet_length(payload_iv) = 12) AND (octet_length(payload_wrapped_key) > 0)))),
    CONSTRAINT event_failure_event_digest_ck CHECK (((payload_digest)::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT event_failure_event_headers_ck CHECK ((jsonb_typeof(source_headers) = 'array'::text)),
    CONSTRAINT event_failure_event_ordinal_ck CHECK ((event_ordinal >= 0)),
    CONSTRAINT event_failure_event_payload_storage_ck CHECK (((((payload_storage)::text = 'DATABASE_PLAIN'::text) AND (payload_plain IS NOT NULL) AND (octet_length(payload_plain) > 0) AND ((payload_digest)::text = encode(sha256(payload_plain), 'hex'::text)) AND (payload_ciphertext IS NULL) AND (payload_object_uri IS NULL) AND (payload_object_version IS NULL) AND (payload_key_id IS NULL) AND (payload_wrapped_key IS NULL) AND (payload_iv IS NULL) AND (payload_deleted_ts IS NULL) AND (payload_deleted_reason IS NULL)) OR (((payload_storage)::text = 'DATABASE'::text) AND (payload_plain IS NULL) AND (payload_ciphertext IS NOT NULL) AND (payload_object_uri IS NULL) AND (payload_object_version IS NULL) AND (payload_key_id IS NOT NULL) AND (payload_wrapped_key IS NOT NULL) AND (payload_iv IS NOT NULL) AND (payload_deleted_ts IS NULL) AND (payload_deleted_reason IS NULL)) OR (((payload_storage)::text = 'OBJECT'::text) AND (payload_plain IS NULL) AND (payload_ciphertext IS NULL) AND (payload_object_uri IS NOT NULL) AND (payload_object_version IS NOT NULL) AND (payload_key_id IS NOT NULL) AND (payload_wrapped_key IS NOT NULL) AND (payload_iv IS NOT NULL) AND (payload_deleted_ts IS NULL) AND (payload_deleted_reason IS NULL)) OR (((payload_storage)::text = 'DELETED'::text) AND (payload_plain IS NULL) AND (payload_ciphertext IS NULL) AND (payload_object_uri IS NULL) AND (payload_object_version IS NULL) AND (payload_key_id IS NULL) AND (payload_wrapped_key IS NULL) AND (payload_iv IS NULL) AND (payload_deleted_ts IS NOT NULL) AND (length(btrim((payload_deleted_reason)::text)) > 0)))),
    CONSTRAINT event_failure_event_processor_ck CHECK (((source_processor)::text = ANY (ARRAY[('DATABASE'::character varying)::text, ('KAFKA'::character varying)::text]))),
