    CONSTRAINT event_failure_publish_outbox_attempt_ck CHECK ((attempt_count >= 0)),
    CONSTRAINT event_failure_publish_outbox_error_time_ck CHECK ((((first_error_ts IS NULL) AND (last_error_ts IS NULL)) OR ((first_error_ts IS NOT NULL) AND (last_error_ts IS NOT NULL) AND (last_error_ts >= first_error_ts)))),
    CONSTRAINT event_failure_publish_outbox_retry_ck CHECK (((((status)::text = 'PENDING'::text) AND (next_attempt_ts IS NULL) AND (published_ts IS NULL)) OR (((status)::text = 'RETRY_WAIT'::text) AND (next_attempt_ts IS NOT NULL) AND (published_ts IS NULL)) OR (((status)::text = 'PUBLISHED'::text) AND (next_attempt_ts IS NULL) AND (published_ts IS NOT NULL)) OR (((status)::text = 'TERMINAL_FAILED'::text) AND (next_attempt_ts IS NULL) AND (published_ts IS NULL)))),
    CONSTRAINT event_failure_publish_outbox_status_ck CHECK (((status)::text = ANY (ARRAY[('PENDING'::character varying)::text, ('RETRY_WAIT'::character varying)::text, ('PUBLISHED'::character varying)::text, ('TERMINAL_FAILED'::character varying)::text])))
);


