-- Name: event_failure_transaction_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.event_failure_transaction_t (
    host_id uuid NOT NULL,
    failure_id uuid NOT NULL,
    projection_name character varying(128) NOT NULL,
    consumer_group character varying(255) NOT NULL,
    first_source_processor character varying(16) NOT NULL,
    original_transaction_id character varying(255) NOT NULL,
    content_fingerprint character varying(64) NOT NULL,
    event_count integer NOT NULL,
    encrypted_payload_bytes bigint DEFAULT 0 NOT NULL,
    decrypted_payload_bytes bigint DEFAULT 0 NOT NULL,
    dependency_scopes jsonb DEFAULT '[]'::jsonb NOT NULL,
    status character varying(16) DEFAULT 'OPEN'::character varying NOT NULL,
    error_type character varying(255),
    error_code character varying(128),
    error_message character varying(2048),
    failure_count integer DEFAULT 1 NOT NULL,
    first_failed_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    last_failed_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    resolved_ts timestamp with time zone,
    resolved_by_request_id uuid,
    legal_hold boolean DEFAULT false NOT NULL,
    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    policy_registry_version character varying(64) DEFAULT 'event-replay-policy-v1'::character varying NOT NULL,
    resolution_code character varying(64),
    resolved_by_repair_id uuid,
    CONSTRAINT event_failure_transaction_counts_ck CHECK (((event_count > 0) AND (failure_count > 0) AND (encrypted_payload_bytes >= 0) AND (decrypted_payload_bytes >= 0))),
    CONSTRAINT event_failure_transaction_fingerprint_ck CHECK (((content_fingerprint)::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT event_failure_transaction_policy_version_v2_ck CHECK ((length(btrim((policy_registry_version)::text)) > 0)),
    CONSTRAINT event_failure_transaction_processor_ck CHECK (((first_source_processor)::text = ANY (ARRAY[('DATABASE'::character varying)::text, ('KAFKA'::character varying)::text]))),
    CONSTRAINT event_failure_transaction_resolution_v2_ck CHECK ((((resolution_code IS NULL) AND (resolved_by_repair_id IS NULL)) OR (((status)::text = 'RESOLVED'::text) AND ((resolution_code)::text = 'RESOLVED_BY_EXACT_REPLAY'::text) AND (resolved_by_repair_id IS NULL)) OR (((status)::text = 'RESOLVED'::text) AND ((resolution_code)::text = 'RESOLVED_BY_REPAIR'::text) AND (resolved_by_repair_id IS NOT NULL)))),
    CONSTRAINT event_failure_transaction_scopes_ck CHECK ((jsonb_typeof(dependency_scopes) = 'array'::text)),
    CONSTRAINT event_failure_transaction_status_ck CHECK (((status)::text = ANY (ARRAY[('OPEN'::character varying)::text, ('RESOLVED'::character varying)::text, ('WAIVED'::character varying)::text]))),
    CONSTRAINT event_failure_transaction_terminal_ck CHECK (((((status)::text = 'OPEN'::text) AND (resolved_ts IS NULL) AND (resolved_by_request_id IS NULL)) OR (((status)::text = 'RESOLVED'::text) AND (resolved_ts IS NOT NULL) AND (resolved_by_request_id IS NOT NULL)) OR (((status)::text = 'WAIVED'::text) AND (resolved_ts IS NOT NULL) AND (resolved_by_request_id IS NULL)))),
    CONSTRAINT event_failure_transaction_time_ck CHECK ((last_failed_ts >= first_failed_ts))
);


