CREATE TABLE public.event_projection_control_t (
    host_id uuid NOT NULL,
    control_id uuid NOT NULL,
    projection_name character varying(128) NOT NULL,
    consumer_group character varying(255) NOT NULL,
    scope_type character varying(32) NOT NULL,
    scope_key character varying(1024) NOT NULL,
    requested_state character varying(32) NOT NULL,
    control_epoch bigint NOT NULL,
    replay_request_id uuid,
    acknowledgement_deadline_ts timestamp with time zone,
    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT event_projection_control_epoch_ck CHECK ((control_epoch >= 0)),
    CONSTRAINT event_projection_control_owner_ck CHECK (((((requested_state)::text = 'RUNNING'::text) AND (replay_request_id IS NULL)) OR (((requested_state)::text <> 'RUNNING'::text) AND (replay_request_id IS NOT NULL)))),
    CONSTRAINT event_projection_control_scope_ck CHECK ((((scope_type)::text = ANY (ARRAY[('HOST'::character varying)::text, ('DB_PARTITION'::character varying)::text, ('KAFKA_PARTITION'::character varying)::text, ('PROJECTION'::character varying)::text])) AND (length(btrim((scope_key)::text)) > 0))),
    CONSTRAINT event_projection_control_state_ck CHECK (((requested_state)::text = ANY (ARRAY[('RUNNING'::character varying)::text, ('PAUSE_REQUESTED'::character varying)::text, ('PAUSED_FOR_REPLAY'::character varying)::text, ('RESUME_REQUESTED'::character varying)::text])))
);


