--
-- Name: event_projection_deferred_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.event_projection_deferred_t (
    host_id uuid NOT NULL,
    deferred_id uuid NOT NULL,
    barrier_id uuid NOT NULL,
    failure_id uuid,
    original_transaction_id character varying(255) NOT NULL,
    content_fingerprint character varying(64) NOT NULL,
    source_processor character varying(16) NOT NULL,
    source_order_key character varying(1024) NOT NULL,
    source_coordinates jsonb NOT NULL,
    event_count integer NOT NULL,
    encrypted_payload_bytes bigint NOT NULL,
    decrypted_payload_bytes bigint NOT NULL,
    dependency_scopes jsonb DEFAULT '[]'::jsonb NOT NULL,
    payload_digest character varying(64) NOT NULL,
    payload_storage character varying(16) NOT NULL,
    payload_plain bytea,
    payload_ciphertext bytea,
    payload_object_uri character varying(2048),
    payload_object_version character varying(255),
    payload_key_id character varying(255),
    payload_wrapped_key bytea,
    payload_iv bytea,
    status character varying(16) DEFAULT 'PENDING'::character varying NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    error_code character varying(128),
    error_message character varying(2048),
    deferred_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    completed_ts timestamp with time zone,
    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT event_projection_deferred_counts_ck CHECK (((event_count > 0) AND (encrypted_payload_bytes >= 0) AND (decrypted_payload_bytes >= 0) AND (attempt_count >= 0) AND (jsonb_typeof(dependency_scopes) = 'array'::text))),
    CONSTRAINT event_projection_deferred_crypto_ck CHECK ((((payload_storage)::text = 'DATABASE_PLAIN'::text) OR ((octet_length(payload_iv) = 12) AND (octet_length(payload_wrapped_key) > 0) AND (length(btrim((payload_key_id)::text)) > 0)))),
    CONSTRAINT event_projection_deferred_fingerprint_ck CHECK ((((content_fingerprint)::text ~ '^[0-9a-f]{64}$'::text) AND ((payload_digest)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT event_projection_deferred_payload_storage_ck CHECK (((((payload_storage)::text = 'DATABASE_PLAIN'::text) AND (payload_plain IS NOT NULL) AND ((payload_digest)::text = encode(sha256(payload_plain), 'hex'::text)) AND (encrypted_payload_bytes = 0) AND (decrypted_payload_bytes = octet_length(payload_plain)) AND (payload_ciphertext IS NULL) AND (payload_object_uri IS NULL) AND (payload_object_version IS NULL) AND (payload_key_id IS NULL) AND (payload_wrapped_key IS NULL) AND (payload_iv IS NULL)) OR (((payload_storage)::text = 'DATABASE'::text) AND (payload_plain IS NULL) AND (payload_ciphertext IS NOT NULL) AND (payload_object_uri IS NULL) AND (payload_object_version IS NULL)) OR (((payload_storage)::text = 'OBJECT'::text) AND (payload_plain IS NULL) AND (payload_ciphertext IS NULL) AND (payload_object_uri IS NOT NULL) AND (payload_object_version IS NOT NULL)))),
    CONSTRAINT event_projection_deferred_processor_ck CHECK ((((source_processor)::text = ANY (ARRAY[('DATABASE'::character varying)::text, ('KAFKA'::character varying)::text])) AND (jsonb_typeof(source_coordinates) = 'object'::text))),
    CONSTRAINT event_projection_deferred_status_ck CHECK (((status)::text = ANY (ARRAY[('PENDING'::character varying)::text, ('RUNNING'::character varying)::text, ('SUCCEEDED'::character varying)::text, ('FAILED'::character varying)::text]))),
    CONSTRAINT event_projection_deferred_terminal_ck CHECK (((((status)::text = ANY (ARRAY[('PENDING'::character varying)::text, ('RUNNING'::character varying)::text])) AND (completed_ts IS NULL) AND (failure_id IS NULL)) OR (((status)::text = 'SUCCEEDED'::text) AND (completed_ts IS NOT NULL) AND (failure_id IS NULL)) OR (((status)::text = 'FAILED'::text) AND (completed_ts IS NOT NULL) AND (failure_id IS NOT NULL))))
);


