CREATE TABLE public.event_projection_worker_t (
    host_id uuid NOT NULL,
    worker_id character varying(255) NOT NULL,
    projection_name character varying(128) NOT NULL,
    consumer_group character varying(255) NOT NULL,
    source_processor character varying(16) NOT NULL,
    source_partition_key character varying(512) NOT NULL,
    control_id uuid,
    observed_epoch bigint DEFAULT 0 NOT NULL,
    acknowledged_epoch bigint DEFAULT 0 NOT NULL,
    state character varying(16) DEFAULT 'RUNNING'::character varying NOT NULL,
    assignment_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    heartbeat_ts timestamp with time zone NOT NULL,
    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT event_projection_worker_control_state_ck CHECK ((((state)::text <> ALL (ARRAY[('PAUSING'::character varying)::text, ('PAUSED'::character varying)::text])) OR (control_id IS NOT NULL))),
    CONSTRAINT event_projection_worker_epoch_ck CHECK (((observed_epoch >= 0) AND (acknowledged_epoch >= 0) AND (acknowledged_epoch <= observed_epoch))),
    CONSTRAINT event_projection_worker_metadata_ck CHECK ((jsonb_typeof(assignment_metadata) = 'object'::text)),
    CONSTRAINT event_projection_worker_processor_ck CHECK (((source_processor)::text = ANY (ARRAY[('DATABASE'::character varying)::text, ('KAFKA'::character varying)::text]))),
    CONSTRAINT event_projection_worker_state_ck CHECK (((state)::text = ANY (ARRAY[('RUNNING'::character varying)::text, ('PAUSING'::character varying)::text, ('PAUSED'::character varying)::text, ('STOPPED'::character varying)::text])))
);


