    corrected_payload_key_id character varying(255),
    corrected_payload_wrapped_key bytea,
    corrected_payload_iv bytea,
    corrected_payload_bytes bigint NOT NULL,
    corrected_event_schema_version character varying(64) NOT NULL,
    changed_field_names jsonb NOT NULL,
    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT event_repair_event_changed_fields_ck CHECK (public.event_replay_changed_fields_valid_v2(changed_field_names)),
    CONSTRAINT event_repair_event_digests_ck CHECK ((((original_payload_digest)::text ~ '^[0-9a-f]{64}$'::text) AND ((corrected_payload_digest)::text ~ '^[0-9a-f]{64}$'::text) AND ((corrected_payload_digest)::text <> (original_payload_digest)::text))),
    CONSTRAINT event_repair_event_ordinal_ck CHECK ((event_ordinal >= 0)),
    CONSTRAINT event_repair_event_payload_storage_ck CHECK ((((corrected_payload_storage)::text = 'DATABASE_PLAIN'::text) AND (corrected_payload_plain IS NOT NULL) AND (octet_length(corrected_payload_plain) = corrected_payload_bytes) AND (corrected_payload_bytes > 0) AND ((corrected_payload_digest)::text = encode(sha256(corrected_payload_plain), 'hex'::text)) AND (corrected_payload_ciphertext IS NULL) AND (corrected_payload_object_uri IS NULL) AND (corrected_payload_object_version IS NULL) AND (corrected_payload_key_id IS NULL) AND (corrected_payload_wrapped_key IS NULL) AND (corrected_payload_iv IS NULL))),
    CONSTRAINT event_repair_event_schema_ck CHECK ((length(btrim((corrected_event_schema_version)::text)) > 0))
);


