--
-- Name: event_repair_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.event_repair_t (
    host_id uuid NOT NULL,
    repair_id uuid NOT NULL,
    failure_id uuid NOT NULL,
    status character varying(32) DEFAULT 'AWAITING_APPROVAL'::character varying NOT NULL,
    reason character varying(2048) NOT NULL,
    policy_registry_version character varying(64) NOT NULL,
    repair_schema_version character varying(64) NOT NULL,
    original_transaction_fingerprint character varying(64) NOT NULL,
    corrected_transaction_fingerprint character varying(64) NOT NULL,
    changed_event_count integer NOT NULL,
    requested_by character varying(255) NOT NULL,
    requested_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    decision_by character varying(255),
    decision_ts timestamp with time zone,
    approved_by character varying(255),
    approved_ts timestamp with time zone,
    applied_by character varying(255),
    applied_ts timestamp with time zone,
    completed_ts timestamp with time zone,
    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT event_repair_actor_pairs_ck CHECK ((((decision_by IS NULL) = (decision_ts IS NULL)) AND ((approved_by IS NULL) = (approved_ts IS NULL)) AND ((applied_by IS NULL) = (applied_ts IS NULL)) AND ((decision_by IS NULL) OR ((decision_by)::text <> (requested_by)::text)) AND ((approved_by IS NULL) OR ((approved_by)::text <> (requested_by)::text)))),
    CONSTRAINT event_repair_count_ck CHECK ((changed_event_count > 0)),
    CONSTRAINT event_repair_fingerprints_ck CHECK ((((original_transaction_fingerprint)::text ~ '^[0-9a-f]{64}$'::text) AND ((corrected_transaction_fingerprint)::text ~ '^[0-9a-f]{64}$'::text) AND ((corrected_transaction_fingerprint)::text <> (original_transaction_fingerprint)::text))),
    CONSTRAINT event_repair_lifecycle_ck CHECK (((((status)::text = 'AWAITING_APPROVAL'::text) AND (decision_by IS NULL) AND (approved_by IS NULL) AND (applied_by IS NULL) AND (completed_ts IS NULL)) OR (((status)::text = 'APPROVED'::text) AND (decision_by IS NOT NULL) AND ((approved_by)::text = (decision_by)::text) AND (approved_ts = decision_ts) AND (applied_by IS NULL) AND (completed_ts IS NULL)) OR (((status)::text = 'APPLIED'::text) AND (decision_by IS NOT NULL) AND ((approved_by)::text = (decision_by)::text) AND (approved_ts = decision_ts) AND (applied_by IS NOT NULL) AND (completed_ts = applied_ts)) OR (((status)::text = 'REJECTED'::text) AND (decision_by IS NOT NULL) AND (approved_by IS NULL) AND (applied_by IS NULL) AND (completed_ts = decision_ts)) OR (((status)::text = 'CANCELLED'::text) AND (applied_by IS NULL) AND (completed_ts IS NOT NULL) AND (((decision_by IS NULL) AND (approved_by IS NULL)) OR ((decision_by IS NOT NULL) AND ((approved_by)::text = (decision_by)::text) AND (approved_ts = decision_ts)))))),
    CONSTRAINT event_repair_reason_ck CHECK ((length(btrim((reason)::text)) > 0)),
    CONSTRAINT event_repair_status_ck CHECK (((status)::text = ANY (ARRAY[('AWAITING_APPROVAL'::character varying)::text, ('APPROVED'::character varying)::text, ('APPLIED'::character varying)::text, ('CANCELLED'::character varying)::text, ('REJECTED'::character varying)::text]))),
    CONSTRAINT event_repair_times_ck CHECK (((created_ts >= requested_ts) AND (updated_ts >= requested_ts) AND ((decision_ts IS NULL) OR (decision_ts >= requested_ts)) AND ((approved_ts IS NULL) OR (approved_ts >= requested_ts)) AND ((applied_ts IS NULL) OR (applied_ts >= approved_ts)) AND ((completed_ts IS NULL) OR (completed_ts >= requested_ts)))),
    CONSTRAINT event_repair_versions_ck CHECK (((length(btrim((policy_registry_version)::text)) > 0) AND (length(btrim((repair_schema_version)::text)) > 0)))
);


