    state character varying(16) NOT NULL,
    owner_type character varying(32) NOT NULL,
    replay_request_id uuid,
    quarantine_failure_id uuid,
    barrier_epoch bigint NOT NULL,
    fencing_token bigint DEFAULT 0 NOT NULL,
    released_by character varying(255),
    release_reason character varying(2048),
    released_ts timestamp with time zone,
    installed_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT event_replay_barrier_epoch_ck CHECK (((barrier_epoch > 0) AND (fencing_token >= 0))),
    CONSTRAINT event_replay_barrier_owner_ck CHECK (((((owner_type)::text = 'REPLAY_REQUEST'::text) AND ((state)::text <> 'QUARANTINED'::text) AND (replay_request_id IS NOT NULL) AND (quarantine_failure_id IS NULL)) OR (((owner_type)::text = 'FAILURE_QUARANTINE'::text) AND ((state)::text = 'QUARANTINED'::text) AND (replay_request_id IS NULL) AND (quarantine_failure_id IS NOT NULL)))),
    CONSTRAINT event_replay_barrier_release_ck CHECK ((((released_ts IS NULL) AND (released_by IS NULL) AND (release_reason IS NULL)) OR ((released_ts IS NOT NULL) AND (released_by IS NOT NULL) AND (release_reason IS NOT NULL) AND (length(btrim((release_reason)::text)) > 0)))),
    CONSTRAINT event_replay_barrier_scope_ck CHECK ((((scope_type)::text = ANY (ARRAY[('GRAPH_ROOT'::character varying)::text, ('AGGREGATE'::character varying)::text, ('HOST'::character varying)::text, ('DB_PARTITION'::character varying)::text, ('KAFKA_PARTITION'::character varying)::text, ('PROJECTION'::character varying)::text])) AND (length(btrim((scope_key)::text)) > 0))),
    CONSTRAINT event_replay_barrier_state_ck CHECK (((state)::text = ANY (ARRAY[('INSTALLING'::character varying)::text, ('ACTIVE'::character varying)::text, ('DRAINING'::character varying)::text, ('QUARANTINED'::character varying)::text])))
);


