    CONSTRAINT event_replay_item_ordinal_ck CHECK ((item_ordinal >= 0)),
    CONSTRAINT event_replay_item_reason_ck CHECK ((length(btrim((dependency_reason)::text)) > 0)),
    CONSTRAINT event_replay_item_status_ck CHECK (((status)::text = ANY (ARRAY[('PENDING'::character varying)::text, ('RUNNING'::character varying)::text, ('SUCCEEDED'::character varying)::text, ('FAILED'::character varying)::text])))
);


