--
-- Name: event_replay_request_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.event_replay_request_t (
    host_id uuid NOT NULL,
    replay_request_id uuid NOT NULL,
    projection_name character varying(128) NOT NULL,
    consumer_group character varying(255) NOT NULL,
    selection_strategy character varying(32) NOT NULL,
    validation_mode character varying(32) NOT NULL,
    reason character varying(2048) NOT NULL,
    plan_hash character varying(64),
    policy_registry_version character varying(64) NOT NULL,
    plan_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    status character varying(32) DEFAULT 'PLANNING'::character varying NOT NULL,
    transaction_count integer DEFAULT 0 NOT NULL,
    event_count integer DEFAULT 0 NOT NULL,
    encrypted_payload_bytes bigint DEFAULT 0 NOT NULL,
    decrypted_payload_bytes bigint DEFAULT 0 NOT NULL,
    requested_by character varying(255) NOT NULL,
    requested_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    approved_by character varying(255),
    approved_ts timestamp with time zone,
    started_by character varying(255),
    started_ts timestamp with time zone,
    completed_ts timestamp with time zone,
    expires_ts timestamp with time zone NOT NULL,
    failure_code character varying(128),
    failure_message character varying(2048),
    fencing_token bigint DEFAULT 0 NOT NULL,
    isolation_mode character varying(32),
    installed_barrier_epoch bigint,
    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    repair_schema_version character varying(64),
    CONSTRAINT event_replay_request_approval_ck CHECK ((((approved_by IS NULL) = (approved_ts IS NULL)) AND (((status)::text <> ALL (ARRAY[('APPROVED'::character varying)::text, ('INSTALLING_BARRIER'::character varying)::text, ('RUNNING'::character varying)::text, ('SUCCEEDED'::character varying)::text])) OR (approved_ts IS NOT NULL)))),
    CONSTRAINT event_replay_request_completed_ck CHECK ((((status)::text = ANY (ARRAY[('SUCCEEDED'::character varying)::text, ('FAILED'::character varying)::text, ('CANCELLED'::character varying)::text, ('EXPIRED'::character varying)::text])) = (completed_ts IS NOT NULL))),
    CONSTRAINT event_replay_request_counts_ck CHECK (((transaction_count >= 0) AND (event_count >= 0) AND (encrypted_payload_bytes >= 0) AND (decrypted_payload_bytes >= 0))),
    CONSTRAINT event_replay_request_expiry_ck CHECK ((expires_ts > requested_ts)),
    CONSTRAINT event_replay_request_fence_ck CHECK (((fencing_token >= 0) AND ((installed_barrier_epoch IS NULL) OR (installed_barrier_epoch > 0)))),
    CONSTRAINT event_replay_request_isolation_ck CHECK (((isolation_mode IS NULL) OR ((isolation_mode)::text = ANY (ARRAY[('GRAPH_ROOT'::character varying)::text, ('AGGREGATE'::character varying)::text, ('HOST'::character varying)::text, ('DB_PARTITION'::character varying)::text, ('KAFKA_PARTITION'::character varying)::text, ('PROJECTION'::character varying)::text])))),
    CONSTRAINT event_replay_request_metadata_ck CHECK ((jsonb_typeof(plan_metadata) = 'object'::text)),
    CONSTRAINT event_replay_request_mode_ck CHECK (((validation_mode)::text = ANY (ARRAY[('VALIDATE_ONLY'::character varying)::text, ('ROLLBACK_DRY_RUN'::character varying)::text, ('EXECUTE'::character varying)::text]))),
    CONSTRAINT event_replay_request_plan_hash_ck CHECK (((plan_hash IS NULL) OR ((plan_hash)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT event_replay_request_planned_ck CHECK ((((status)::text = 'PLANNING'::text) OR ((status)::text = 'FAILED'::text) OR ((plan_hash IS NOT NULL) AND (transaction_count > 0) AND (event_count > 0)))),
    CONSTRAINT event_replay_request_reason_ck CHECK ((length(btrim((reason)::text)) > 0)),
    CONSTRAINT event_replay_request_repair_schema_v2_ck CHECK (((repair_schema_version IS NULL) OR (length(btrim((repair_schema_version)::text)) > 0))),
    CONSTRAINT event_replay_request_started_ck CHECK ((((started_by IS NULL) = (started_ts IS NULL)) AND (((status)::text <> ALL (ARRAY[('RUNNING'::character varying)::text, ('SUCCEEDED'::character varying)::text])) OR (started_ts IS NOT NULL)))),
    CONSTRAINT event_replay_request_status_ck CHECK (((status)::text = ANY (ARRAY[('PLANNING'::character varying)::text, ('READY'::character varying)::text, ('AWAITING_APPROVAL'::character varying)::text, ('APPROVED'::character varying)::text, ('INSTALLING_BARRIER'::character varying)::text, ('RUNNING'::character varying)::text, ('SUCCEEDED'::character varying)::text, ('FAILED'::character varying)::text, ('CANCELLED'::character varying)::text, ('EXPIRED'::character varying)::text]))),
    CONSTRAINT event_replay_request_strategy_ck CHECK (((selection_strategy)::text = ANY (ARRAY[('EXACT'::character varying)::text, ('DEPENDENCY_CLOSURE'::character varying)::text])))
);


