CREATE TABLE public.event_replay_retention_log_t (
    host_id uuid,
    retention_id uuid NOT NULL,
    subject_type character varying(32) NOT NULL,
    subject_id character varying(255) NOT NULL,
    outcome character varying(32) NOT NULL,
    reason character varying(1024) NOT NULL,
    details jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT event_replay_retention_log_details_ck CHECK ((jsonb_typeof(details) = 'object'::text)),
    CONSTRAINT event_replay_retention_log_outcome_ck CHECK (((outcome)::text = ANY (ARRAY[('DELETED'::character varying)::text, ('SKIPPED_LEGAL_HOLD'::character varying)::text, ('SKIPPED_ACTIVE'::character varying)::text, ('FAILED'::character varying)::text, ('ORPHAN_DELETED'::character varying)::text]))),
    CONSTRAINT event_replay_retention_log_reason_ck CHECK ((length(btrim((reason)::text)) > 0)),
    CONSTRAINT event_replay_retention_log_subject_ck CHECK ((((subject_type)::text = ANY (ARRAY[('PAYLOAD'::character varying)::text, ('FAILURE_METADATA'::character varying)::text, ('REPLAY_METADATA'::character varying)::text, ('AUDIT'::character varying)::text, ('PUBLICATION_OUTBOX'::character varying)::text, ('OBJECT_RECONCILIATION'::character varying)::text])) AND (length(btrim((subject_id)::text)) > 0)))
);


