-- Name: instance_clone_request_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.instance_clone_request_t (
    host_id uuid NOT NULL,
    clone_request_id uuid NOT NULL,
    request_hash character varying(128) NOT NULL,
    source_instance_id uuid NOT NULL,
    source_graph_digest character varying(128) NOT NULL,
    catalog_schema_digest character varying(128) NOT NULL,
    target_instance_id uuid NOT NULL,
    target_instance_name character varying(126) NOT NULL,
    target_service_id character varying(512) NOT NULL,
    target_env_tag character varying(16),
    target_product_version_id uuid NOT NULL,
    transaction_id uuid NOT NULL,
    terminal_event_id uuid NOT NULL,
    snapshot_id uuid,
    clone_status character varying(32) DEFAULT 'ACCEPTED'::character varying NOT NULL,
    event_count integer NOT NULL,
    payload_bytes bigint NOT NULL,
    result_summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_code character varying(64),
    error_message character varying(2048),
    requested_by uuid NOT NULL,
    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT instance_clone_request_event_count_ck CHECK ((event_count >= 0)),
    CONSTRAINT instance_clone_request_payload_bytes_ck CHECK ((payload_bytes >= 0)),
    CONSTRAINT instance_clone_request_result_summary_ck CHECK ((jsonb_typeof(result_summary) = 'object'::text)),
    CONSTRAINT instance_clone_request_snapshot_ck CHECK ((((clone_status)::text <> 'SNAPSHOT_READY'::text) OR (snapshot_id IS NOT NULL))),
    CONSTRAINT instance_clone_request_status_ck CHECK (((clone_status)::text = ANY (ARRAY[('ACCEPTED'::character varying)::text, ('PROJECTED'::character varying)::text, ('SNAPSHOT_READY'::character varying)::text, ('FAILED_DLQ'::character varying)::text])))
);


