    CONSTRAINT knowledge_base_import_t_state_check CHECK (((state)::text = ANY (ARRAY[('DEPENDENCIES_PENDING'::character varying)::text, ('READY_TO_BUILD'::character varying)::text, ('BUILD_APPROVED'::character varying)::text, ('BUILDING'::character varying)::text, ('FAILED_RETRYABLE'::character varying)::text, ('COMPLETED'::character varying)::text, ('ABANDONED'::character varying)::text]))),
