CREATE TABLE public.llm_gateway_publication_t (
    host_id uuid NOT NULL,
    environment character varying(32) NOT NULL,
    gateway_publication_id uuid NOT NULL,
    publication_version bigint NOT NULL,
    manifest jsonb NOT NULL,
    manifest_digest character varying(71) NOT NULL,
    minimum_gateway_version character varying(32) NOT NULL,
    enabled_routing_features jsonb DEFAULT '[]'::jsonb NOT NULL,
    validation_result jsonb DEFAULT '{}'::jsonb NOT NULL,
    publication_state character varying(16) DEFAULT 'CANDIDATE'::character varying NOT NULL,
    rollback_of_publication_id uuid,
    source_digest character varying(71),
    config_properties jsonb,
    config_properties_digest character varying(71),
    delivery_mode character varying(32) DEFAULT 'INSTANCE_PROPERTIES'::character varying NOT NULL,
    aggregate_version bigint DEFAULT 1 NOT NULL,
    active boolean DEFAULT true NOT NULL,
    update_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    update_user character varying(126) DEFAULT SESSION_USER NOT NULL,
    CONSTRAINT llm_gateway_publication_delivery_mode_ck CHECK ((((delivery_mode)::text = 'INSTANCE_PROPERTIES'::text) AND (source_digest IS NOT NULL) AND (config_properties IS NOT NULL) AND (config_properties_digest IS NOT NULL))),
    CONSTRAINT llm_gateway_publication_properties_digest_ck CHECK (((config_properties_digest IS NULL) OR ((config_properties_digest)::text ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT llm_gateway_publication_properties_shape_ck CHECK (((config_properties IS NULL) OR (jsonb_typeof(config_properties) = 'array'::text))),
    CONSTRAINT llm_gateway_publication_source_digest_ck CHECK (((source_digest IS NULL) OR ((source_digest)::text ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT llm_gateway_publication_t_aggregate_version_check CHECK ((aggregate_version > 0)),
    CONSTRAINT llm_gateway_publication_t_enabled_routing_features_check CHECK ((jsonb_typeof(enabled_routing_features) = 'array'::text)),
    CONSTRAINT llm_gateway_publication_t_manifest_check CHECK ((jsonb_typeof(manifest) = 'object'::text)),
    CONSTRAINT llm_gateway_publication_t_manifest_digest_check CHECK (((manifest_digest)::text ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT llm_gateway_publication_t_publication_state_check CHECK (((publication_state)::text = ANY (ARRAY[('CANDIDATE'::character varying)::text, ('VALIDATED'::character varying)::text, ('PUBLISHED'::character varying)::text, ('FAILED'::character varying)::text, ('ROLLED_BACK'::character varying)::text]))),
    CONSTRAINT llm_gateway_publication_t_publication_version_check CHECK ((publication_version > 0)),
    CONSTRAINT llm_gateway_publication_t_validation_result_check CHECK ((jsonb_typeof(validation_result) = 'object'::text))
);


