--
-- Name: llm_pricing_version_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.llm_pricing_version_t (
    host_id uuid NOT NULL,
    pricing_version_id uuid NOT NULL,
    provider_deployment_id uuid NOT NULL,
    pricing_version integer NOT NULL,
    operation character varying(16) NOT NULL,
    input_micros_per_million bigint NOT NULL,
    output_micros_per_million bigint,
    cached_input_micros_per_million bigint,
    effective_ts timestamp with time zone NOT NULL,
    expires_ts timestamp with time zone,
    source character varying(255) NOT NULL,
    approved_by character varying(126) NOT NULL,
    aggregate_version bigint DEFAULT 1 NOT NULL,
    active boolean DEFAULT true NOT NULL,
    update_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    update_user character varying(126) DEFAULT SESSION_USER NOT NULL,
    pricing_basis character varying(24) DEFAULT 'EXTERNAL_PROVIDER'::character varying NOT NULL,
    CONSTRAINT llm_pricing_version_basis_ck CHECK ((((pricing_basis)::text = ANY (ARRAY[('EXTERNAL_PROVIDER'::character varying)::text, ('ZERO_MARGINAL'::character varying)::text, ('AMORTIZED_INTERNAL'::character varying)::text])) AND (((pricing_basis)::text <> 'ZERO_MARGINAL'::text) OR ((input_micros_per_million = 0) AND (COALESCE(output_micros_per_million, (0)::bigint) = 0))) AND (((pricing_basis)::text <> 'AMORTIZED_INTERNAL'::text) OR ((input_micros_per_million > 0) OR (COALESCE(output_micros_per_million, (0)::bigint) > 0))))),
    CONSTRAINT llm_pricing_version_t_aggregate_version_check CHECK ((aggregate_version > 0)),
    CONSTRAINT llm_pricing_version_t_cached_input_micros_per_million_check CHECK (((cached_input_micros_per_million IS NULL) OR (cached_input_micros_per_million >= 0))),
    CONSTRAINT llm_pricing_version_t_check CHECK (((((operation)::text = 'generate'::text) AND (output_micros_per_million IS NOT NULL)) OR (((operation)::text = 'embed'::text) AND (output_micros_per_million IS NULL)))),
    CONSTRAINT llm_pricing_version_t_check1 CHECK (((expires_ts IS NULL) OR (expires_ts > effective_ts))),
    CONSTRAINT llm_pricing_version_t_input_micros_per_million_check CHECK ((input_micros_per_million >= 0)),
    CONSTRAINT llm_pricing_version_t_operation_check CHECK (((operation)::text = ANY (ARRAY[('generate'::character varying)::text, ('embed'::character varying)::text]))),
    CONSTRAINT llm_pricing_version_t_output_micros_per_million_check CHECK (((output_micros_per_million IS NULL) OR (output_micros_per_million >= 0))),
    CONSTRAINT llm_pricing_version_t_pricing_version_check CHECK ((pricing_version > 0))
);


