--
-- Name: llm_provider_credential_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.llm_provider_credential_t (
    host_id uuid NOT NULL,
    provider_credential_id uuid NOT NULL,
    provider_deployment_id uuid,
    credential_version integer NOT NULL,
    secret_reference character varying(1024) NOT NULL,
    effective_ts timestamp with time zone NOT NULL,
    expires_ts timestamp with time zone,
    aggregate_version bigint DEFAULT 1 NOT NULL,
    active boolean DEFAULT true NOT NULL,
    update_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    update_user character varying(126) DEFAULT SESSION_USER NOT NULL,
    provider_endpoint_id uuid,
    credential_purpose character varying(24) DEFAULT 'ENDPOINT'::character varying NOT NULL,
    environment character varying(32),
    reasoning_key_id character varying(255),
    reasoning_key_role character varying(16),
    reasoning_key_set_generation bigint,
    reasoning_key_set_state character varying(16),
    reasoning_state_limits jsonb,
    CONSTRAINT llm_provider_credential_owner_ck CHECK (((((credential_purpose)::text = 'ENDPOINT'::text) AND (provider_endpoint_id IS NOT NULL) AND (provider_deployment_id IS NULL) AND (environment IS NULL) AND (reasoning_key_id IS NULL)) OR (((credential_purpose)::text = 'SIDECAR_RUNTIME'::text) AND (provider_deployment_id IS NOT NULL) AND (provider_endpoint_id IS NULL) AND (environment IS NULL) AND (reasoning_key_id IS NULL)) OR (((credential_purpose)::text = 'REASONING_SEAL'::text) AND (provider_endpoint_id IS NULL) AND (provider_deployment_id IS NULL) AND (environment IS NOT NULL) AND (reasoning_key_id IS NOT NULL) AND ((reasoning_key_role)::text = ANY (ARRAY[('CURRENT'::character varying)::text, ('PREVIOUS'::character varying)::text])) AND (reasoning_key_set_generation > 0) AND ((reasoning_key_set_state)::text = ANY (ARRAY[('PREPARED'::character varying)::text, ('ACTIVE'::character varying)::text])) AND (jsonb_typeof(reasoning_state_limits) = 'object'::text)))),
    CONSTRAINT llm_provider_credential_purpose_ck CHECK (((credential_purpose)::text = ANY (ARRAY[('ENDPOINT'::character varying)::text, ('SIDECAR_RUNTIME'::character varying)::text, ('REASONING_SEAL'::character varying)::text]))),
    CONSTRAINT llm_provider_credential_secret_reference_ck CHECK ((((secret_reference)::text ~ '^env:[A-Za-z_][A-Za-z0-9_]*$'::text) OR ((secret_reference)::text ~ '^[A-Za-z][A-Za-z0-9+.-]*://'::text))),
    CONSTRAINT llm_provider_credential_t_aggregate_version_check CHECK ((aggregate_version > 0)),
    CONSTRAINT llm_provider_credential_t_check CHECK (((expires_ts IS NULL) OR (expires_ts > effective_ts))),
    CONSTRAINT llm_provider_credential_t_credential_version_check CHECK ((credential_version > 0))
);


