    CONSTRAINT outbox_message_t_check CHECK (((transaction_count > 0) AND (transaction_ordinal < transaction_count))),
    CONSTRAINT outbox_message_t_transaction_ordinal_check CHECK ((transaction_ordinal >= 0))
);


