CREATE TABLE public.skill_package_t (
    host_id uuid NOT NULL,
    package_id uuid NOT NULL,
    package_name character varying(255) NOT NULL,
    package_version character varying(64) NOT NULL,
    product_profile character varying(64) NOT NULL,
    object_reference text NOT NULL,
    content_digest character varying(71) NOT NULL,
    media_type character varying(126) NOT NULL,
    size_bytes bigint NOT NULL,
    signer_reference character varying(255) NOT NULL,
    signature_reference text NOT NULL,
    scanner_reference character varying(255) NOT NULL,
    scan_digest character varying(71) NOT NULL,
    provenance_reference text NOT NULL,
    entrypoint character varying(1024) NOT NULL,
    compatibility jsonb NOT NULL,
    instruction_authority character varying(32) NOT NULL,
    state character varying(32) NOT NULL,
    reviewed_by character varying(255) NOT NULL,
    reviewed_ts timestamp with time zone NOT NULL,
    revoked_ts timestamp with time zone,
    revocation_reason text,
    retain_until_ts timestamp with time zone NOT NULL,
    deletion_state character varying(32) DEFAULT 'RETAINED'::character varying NOT NULL,
    deletion_evidence jsonb,
    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT skill_package_t_deletion_state_check CHECK (((deletion_state)::text = ANY (ARRAY[('RETAINED'::character varying)::text, ('DELETE_PENDING'::character varying)::text, ('DELETING'::character varying)::text, ('DELETED'::character varying)::text, ('DELETE_FAILED'::character varying)::text]))),
    CONSTRAINT skill_package_t_instruction_authority_check CHECK (((instruction_authority)::text = ANY (ARRAY[('platform'::character varying)::text, ('product'::character varying)::text, ('administrator'::character varying)::text, ('repository'::character varying)::text, ('generated'::character varying)::text]))),
    CONSTRAINT skill_package_t_product_profile_check CHECK (((product_profile)::text = ANY (ARRAY[('enterprise'::character varying)::text, ('native-workflow'::character varying)::text, ('coding'::character varying)::text, ('personal-assistant'::character varying)::text, ('external-adapter'::character varying)::text]))),
    CONSTRAINT skill_package_t_size_bytes_check CHECK ((size_bytes >= 0)),
    CONSTRAINT skill_package_t_state_check CHECK (((state)::text = ANY (ARRAY[('PUBLISHED'::character varying)::text, ('REVOKED'::character varying)::text, ('RETIRED'::character varying)::text])))
);


