--
-- Name: tool_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tool_t (
    host_id uuid NOT NULL,
    tool_id uuid NOT NULL,
    name character varying(126) NOT NULL,
    description text NOT NULL,
    description_source character varying(32),
    description_manual_override boolean DEFAULT false NOT NULL,
    description_override_ts timestamp with time zone,
    description_override_user character varying(126),
    implementation_type character varying(50),
    implementation_class character varying(500),
    mcp_server_name character varying(126),
    api_endpoint character varying(1024),
    api_method character varying(10),
    endpoint_id uuid,
    capability_ref character varying(512),
    lightapi_document jsonb,
    lightapi_digest character varying(71),
    lightapi_validation_status character varying(16),
    lightapi_validation_errors jsonb DEFAULT '[]'::jsonb,
    lightapi_validated_ts timestamp with time zone,
    script_content text,
    response_schema jsonb,
    tool_metadata jsonb,
    routing_domain character varying(128),
    semantic_namespace character varying(128),
    sensitivity_tier character varying(64),
    semantic_weight real DEFAULT 1.0,
    source_protocol character varying(50),
    lifecycle_status character varying(32) DEFAULT 'active'::character varying,
    cost_tier character varying(32),
    target_personas text,
    description_embedding public.vector(384),
    description_embedding_model character varying(128),
    description_embedding_dimension integer,
    description_embedding_source_hash character varying(64),
    description_embedding_ts timestamp with time zone,
    description_embedding_status character varying(32),
    description_embedding_error text,
    version character varying(20) DEFAULT '1.0.0'::character varying,
    aggregate_version bigint DEFAULT 1 NOT NULL,
    active boolean DEFAULT true,
    update_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    update_user character varying(126) DEFAULT SESSION_USER,
    stable_tool_ref uuid,
    execution_placement character varying(16),
    model_alias character varying(126),
    schema_digest character varying(71),
    dispatch_policy_ref character varying(255),
    script_execution_policy character varying(32) DEFAULT 'AUTHORING_ONLY'::character varying NOT NULL,
    CONSTRAINT chk_tool_cost CHECK ((((cost_tier)::text = ANY (ARRAY[('low'::character varying)::text, ('medium'::character varying)::text, ('high'::character varying)::text])) OR (cost_tier IS NULL))),
    CONSTRAINT chk_tool_lifecycle CHECK (((lifecycle_status IS NOT NULL) AND ((lifecycle_status)::text = ANY (ARRAY[('active'::character varying)::text, ('deprecated'::character varying)::text, ('retired'::character varying)::text])))),
    CONSTRAINT chk_tool_lightapi_digest CHECK (((lightapi_digest IS NULL) OR ((lightapi_digest)::text ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT chk_tool_lightapi_errors CHECK (((lightapi_validation_errors IS NULL) OR (jsonb_typeof(lightapi_validation_errors) = 'array'::text))),
    CONSTRAINT chk_tool_lightapi_status CHECK (((lightapi_validation_status IS NULL) OR ((lightapi_validation_status)::text = ANY (ARRAY[('VALID'::character varying)::text, ('INVALID'::character varying)::text])))),
    CONSTRAINT chk_tool_source_protocol CHECK ((((source_protocol)::text = ANY (ARRAY[('openapi'::character varying)::text, ('mcp'::character varying)::text, ('lightapi'::character varying)::text, ('http'::character varying)::text])) OR (source_protocol IS NULL))),
    CONSTRAINT tool_execution_placement_ck CHECK (((execution_placement IS NULL) OR ((execution_placement)::text = ANY (ARRAY[('gateway'::character varying)::text, ('runner'::character varying)::text, ('workflow'::character varying)::text, ('fixed'::character varying)::text])))),
    CONSTRAINT tool_script_execution_policy_ck CHECK (((script_execution_policy)::text = ANY (ARRAY[('AUTHORING_ONLY'::character varying)::text, ('LEGACY_LOCAL_DISABLED'::character varying)::text])))
);


